       <h1 id="support-title">How can we help?</h1>
       <p>Send our team your contact details and we will route your request to the right support specialist.</p>
     </section>

     <section class="form-card" aria-label="Contact support form">
       <form id="contactForm" novalidate>
         <div class="form-field">
           <label for="fullName">Full name</label>
           <input
             type="text"
             id="fullName"
             name="fullName"
             placeholder="Jordan Lee"
             autocomplete="name"
             aria-describedby="fullNameError"
             required
           >
           <span class="error-message" id="fullNameError" aria-live="polite"></span>
         </div>

         <div class="form-field">
           <label for="email">Email address</label>
           <input
             type="email"
             id="email"
             name="email"
             placeholder="jordan@example.com"
             autocomplete="email"
             aria-describedby="emailError"
             required
           >
           <span class="error-message" id="emailError" aria-live="polite"></span>
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
           <input
             type="tel"
             id="phone"
             name="phone"
             placeholder="+1 555 123 4567"
             autocomplete="tel"
             aria-describedby="phoneHelper phoneError"
           >
           <span class="helper-text" id="phoneHelper">Use international format, for example +1 555 123 4567.</span>
           <span class="error-message" id="phoneError" aria-live="polite"></span>
         </div>

         <p class="success-message" id="successMessage" role="status">Thanks, your support request is ready to send.</p>

         <button type="submit">Submit request</button>
       </form>
     </section>
   </main>

   <script>
